-- Regional clubs persisted in public.teams.
ALTER TABLE public.teams ADD COLUMN IF NOT EXISTS regional_region text;
ALTER TABLE public.teams ADD COLUMN IF NOT EXISTS regional_group text;

GRANT SELECT ON public.teams TO anon, authenticated;
GRANT INSERT, UPDATE, DELETE ON public.teams TO authenticated;

ON CONFLICT (id) DO UPDATE SET regional_region=COALESCE(public.teams.regional_region,EXCLUDED.regional_region), regional_group=COALESCE(public.teams.regional_group,EXCLUDED.regional_group);
-- Ensure the public logo bucket can be read and admins can write logos.
VALUES ('team-logos','team-logos',true)
ON CONFLICT (id) DO UPDATE SET public=true;

DROP POLICY IF EXISTS "team-logos public read" ON storage.objects;
CREATE POLICY "team-logos public read" ON storage.objects
FOR SELECT TO anon, authenticated USING (bucket_id='team-logos');

DROP POLICY IF EXISTS "team-logos admin insert" ON storage.objects;
CREATE POLICY "team-logos admin insert" ON storage.objects
FOR INSERT TO authenticated
WITH CHECK (bucket_id='team-logos' AND public.has_role(auth.uid(),'admin'));

DROP POLICY IF EXISTS "team-logos admin update" ON storage.objects;
CREATE POLICY "team-logos admin update" ON storage.objects
FOR UPDATE TO authenticated
USING (bucket_id='team-logos' AND public.has_role(auth.uid(),'admin'))
WITH CHECK (bucket_id='team-logos' AND public.has_role(auth.uid(),'admin'));
